def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 18.0))

    prev_bids = []
    strong_prev = 0.0
    weak_count = 0
    desperate_count = 0
    for agent_id, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if float(bid) > strong_prev:
                strong_prev = float(bid)
            if float(bid) <= 5:
                weak_count += 1
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 2:
            desperate_count += 1

    alive_count = len(alive)
    supply_ratio = float(supply) / float(WATER_REQ)

    if hp <= 2 or no_water_days >= 2:
        emergency = max(63.0, strong_prev + 2.0)
        return float(min(budget, emergency))

    if supply_ratio >= alive_count + 0.4:
        base = 8.0
    elif supply_ratio >= alive_count:
        base = 16.0
    elif supply_ratio >= max(1, alive_count - 1):
        base = 28.0
    else:
        base = 44.0

    if strong_prev >= 75:
        target = 24.0 if hp >= 4 else 58.0
    elif strong_prev >= 60:
        target = strong_prev + 1.6 if (hp <= 3 or supply_ratio < alive_count) else 26.0
    elif strong_prev >= 40:
        target = max(base, strong_prev + 1.2)
    elif strong_prev > 0:
        target = max(base, strong_prev + 0.8)
    else:
        target = base

    if weak_count >= max(1, alive_count - 1) and hp >= 4:
        target = min(target, 14.0)

    if desperate_count >= 2 and supply_ratio < alive_count:
        target = max(target, 48.0)

    if day >= 8:
        if hp >= 5:
            target = min(target, 22.0)
        else:
            target = max(target, 46.0)

    target = max(0.0, min(float(budget), float(target)))
    return float(target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', True):
            alive_opps.append((oid, o))

    if not alive_opps:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Immediate reaction from yesterday's trace
    prev_bids = []
    prev_by_id = {}
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {})
        b = prev.get('bid', None)
        if b is not None:
            try:
                b = float(b)
            except Exception:
                b = None
        if b is not None:
            prev_bids.append(b)
            prev_by_id[oid] = b

    # Estimate today's needed water to avoid starvation streak
    # If we've already gone multiple days without water, bid more aggressively.
    urgency = 0
    if my_no_water_days >= 2:
        urgency = 2
    elif my_no_water_days == 1:
        urgency = 1

    # Supply-based aggressiveness: higher supply => easier to secure water cheaply.
    supply_factor = 0.55
    if supply >= 21.0:
        supply_factor = 0.45
    elif supply <= 17.0:
        supply_factor = 0.65

    # If someone previously bid very high, they likely want to secure water; counter-bid slightly above.
    if prev_bids:
        highest_prev = max(prev_bids)
        second_prev = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev

        # If Alex is alive and previously bid high, treat as main competitor.
        alex_bid = prev_by_id.get('Alex', None)
        eric_bid = prev_by_id.get('Eric', None)

        # Determine target bid ceiling based on our urgency and hp.
        if my_hp <= 2.0 or urgency >= 2:
            base = DAILY_SALARY * 0.85
        elif my_hp <= 4.0 or urgency == 1:
            base = DAILY_SALARY * 0.65
        else:
            base = DAILY_SALARY * 0.50

        # Counter-bid logic: only pay above if others showed willingness to spend.
        if alex_bid is not None and alex_bid >= DAILY_SALARY * 0.75:
            target = min(my_budget, base)
            # If we can, nudge above Alex's previous bid; otherwise bid near base.
            target = min(my_budget, max(target, alex_bid + 1.0))
            return max(0.0, min(target, DAILY_SALARY * 0.95))

        if highest_prev >= DAILY_SALARY * 0.6:
            # Compete for water; just above the leader but capped.
            target = min(my_budget, (highest_prev + 1.5) * 1.0)
            # If we're healthy and supply is high, don't overpay.
            if my_hp > 6.0 and supply >= 21.0:
                target = min(target, DAILY_SALARY * 0.55)
            return max(0.0, min(target, DAILY_SALARY * 0.9))

        # If nobody bid huge, bid modestly to secure.
        # Use second-highest as a soft guide.
        target = min(my_budget, max(DAILY_SALARY * supply_factor, (second_prev * 0.75) + 5.0))
        if my_hp <= 3.0:
            target = min(my_budget, max(target, DAILY_SALARY * 0.75))
        return max(0.0, min(target, DAILY_SALARY * 0.8))

    # Fallback: no previous bids available
    if my_hp <= 2.0 or urgency >= 2:
        return min(my_budget, DAILY_SALARY * 0.9)
    if my_hp <= 4.0 or urgency == 1:
        return min(my_budget, DAILY_SALARY * 0.7)
    return min(my_budget, DAILY_SALARY * 0.55)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Collect yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Base bid calculation
    if yesterday_bids:
        avg_yesterday = sum(yesterday_bids) / len(yesterday_bids)
        # If we are desperate, bid above average to guarantee water
        if my_status['hp'] <= 3 or my_status['no_water_days'] >= 2:
            target_bid = min(avg_yesterday + 3, DAILY_SALARY * 0.85)
        else:
            # Conservative: bid below average, rely on supply
            target_bid = max(DAILY_SALARY * 0.3, avg_yesterday - 5)
    else:
        # No trace info, use default
        if my_status['hp'] <= 3:
            target_bid = DAILY_SALARY * 0.8
        else:
            target_bid = DAILY_SALARY * 0.4

    # Adjust based on supply (high supply means more water available, lower bid needed)
    supply = day_context['supply']
    if supply > 20:
        target_bid *= 0.85
    elif supply < 17:
        target_bid *= 1.15

    # Ensure not exceeding budget and not less than 0
    target_bid = max(0, min(my_status['budget'], target_bid))
    return target_bid
